SQL_DOC.P_SQL:
SELECT COMPANY ,PLANT ,LEGACY_PO_NO ,LEGACY_PO_SEQ ,LEGACY_PO_CNT ,DS_SEQ ,STATUS ,DS_QTY ,DS_DATE ,IF_DATE ,IF_TIME ,IF_FLAG FROM IF_UCUBE_DS_SEND WHERE COMPANY = '$G_RS.COMPANY$' AND LEGACY_PO_NO = '$G_RS.LEGACY_PO_NO$' AND LEGACY_PO_SEQ = '$G_RS.LEGACY_PO_SEQ$' AND LEGACY_PO_CNT = '$G_RS.LEGACY_PO_CNT$' AND DS_SEQ = '$G_RS.DS_SEQ$' AND IF_FLAG = 'N'
BEGIN UPDATE IF_UCUBE_DS_SEND SET IF_FLAG = 'Y' ,IF_DATE = to_char(SYSDATE,'YYYYMMDD') ,IF_TIME = to_char(SYSDATE,'HH24MISS') WHERE COMPANY = '$G_RS.COMPANY$' AND LEGACY_PO_NO = '$G_RS.LEGACY_PO_NO$' AND LEGACY_PO_SEQ = '$G_RS.LEGACY_PO_SEQ$' AND LEGACY_PO_CNT = '$G_RS.LEGACY_PO_CNT$' AND DS_SEQ = '$G_RS.DS_SEQ$' AND IF_FLAG = 'N'; END;
BEGIN UPDATE IF_UCUBE_DS_SEND SET IF_FLAG = 'E' ,IF_DATE = to_char(SYSDATE,'YYYYMMDD') ,IF_TIME = to_char(SYSDATE,'HH24MISS') WHERE COMPANY = '$G_RS.COMPANY$' AND LEGACY_PO_NO = '$G_RS.LEGACY_PO_NO$' AND LEGACY_PO_SEQ = '$G_RS.LEGACY_PO_SEQ$' AND LEGACY_PO_CNT = '$G_RS.LEGACY_PO_CNT$' AND DS_SEQ = '$G_RS.DS_SEQ$' AND IF_FLAG = 'N'; END;
